def solve(*args) -> int:
    """Return the Levenshtein edit distance between two strings.
    If called with two arguments, they are taken as the strings.
    Otherwise, two lines are read from standard input.
    """
    if len(args) == 2:
        a, b = args
    else:
        data = sys.stdin.read().splitlines()
        if len(data) >= 2:
            a, b = data[0], data[1]
        elif len(data) == 1:
            a, b = data[0], ''
        else:
            a = b = ''
    n, m = len(a), len(b)
    # Ensure that m is the smaller length for O(m) space
    if n < m:
        a, b = b, a
        n, m = m, n
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            cost = 0 if ai == b[j - 1] else 1
            cur[j] = min(prev[j] + 1,      # deletion
                         cur[j - 1] + 1,  # insertion
                         prev[j - 1] + cost)  # substitution
        prev = cur
    return prev[m]
"}

