import sys

def solve(*args):
    """Check if brackets in a string are balanced.
    Accepts an argument string or reads from stdin (first line).
    Returns True if (), [], {} are properly nested, ignoring other chars.
    """
    if args:
        s = str(args[0])
    else:
        data = sys.stdin.read().splitlines()
        s = data[0] if data else ''
    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}
    closing = set(pairs.values())
    for ch in s:
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closing:
            if not stack or stack.pop() != ch:
                return False
    return not stack

