def solve(*args):
    """Evaluate an expression in Reverse Polish Notation.
    If a single argument is provided, it should be an iterable of tokens (strings or numbers).
    If called with no arguments, reads a line from stdin, splits by whitespace into tokens.
    Returns the integer result.
    Supported operators: +, -, *, / (integer division truncating toward zero).
    """
    if args:
        tokens = list(args[0])
    else:
        tokens = sys.stdin.read().strip().split()
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero like int(a / b)
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

