import sys

def solve(*args):
    """Merge overlapping intervals.
    If called with one argument, it should be an iterable of [start, end] pairs.
    Otherwise, reads from stdin: first integer n, then n lines each with two ints.
    Returns a list of merged intervals sorted by start.
    """
    if args:
        intervals = [list(pair) for pair in args[0]]
    else:
        data = sys.stdin.read().strip().split()
        if not data:
            return []
        it = iter(data)
        n = int(next(it))
        intervals = []
        for _ in range(n):
            start = int(next(it))
            end = int(next(it))
            intervals.append([start, end])
    if not intervals:
        return []
    intervals.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = intervals[0]
    for start, end in intervals[1:]:
        if start <= cur_end:
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

