import sys

def solve(*args):
    """Run-length encode a string.
    If an argument is provided, it is used as the string.
    Otherwise, reads the entire stdin input (stripping a trailing newline).
    Returns a list of [character, count] pairs.
    """
    if args:
        s = str(args[0])
    else:
        s = sys.stdin.read()
        if s.endswith('\n'):
            s = s[:-1]
        if s.endswith('\r'):
            s = s[:-1]
    if not s:
        return []
    result = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            result.append([cur, cnt])
            cur = ch
            cnt = 1
    result.append([cur, cnt])
    return result

