def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    cols = max((len(row) for row in grid), default=0)
    visited = [[False] * cols for _ in range(rows)]
    count = 0

    def dfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = cr + dr, cc + dc
                if (0 <= nr < rows and 0 <= nc < cols
                        and nc < len(grid[nr]) and grid[nr][nc] == 1
                        and not visited[nr][nc]):
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                dfs(r, c)
    return count

